const tick = (flow.get("tick") || 0) + 1;
flow.set("tick", tick);

const timestamp = new Date().toISOString();
const round = number => Number(number.toFixed(2));
const motors = [
    { device_id: "motor-01", temperature: 47, vibration: 1.9, rpm: 1450 },
    { device_id: "motor-02", temperature: 51, vibration: 2.3, rpm: 1490 }
];
const readings = motors.map((motor, index) => {
    const phase = tick / 5 + index;
    const fault = index === 1 ? Math.min(tick * 0.045, 3.5) : 0;
    return {
        device_id: motor.device_id,
        timestamp,
        quality: "good",
        values: {
            temperature_c: round(motor.temperature + Math.sin(phase) * 0.8 + fault * 1.2),
            vibration_mm_s: round(motor.vibration + Math.sin(phase * 1.7) * 0.2 + fault),
            rpm: Math.round(motor.rpm + Math.sin(phase) * 8)
        }
    };
});
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = { schema_version: "1.0", source: "iotlink-master-simulated", generated_at: timestamp, readings };
return msg;

